<?php
require 'config.php';
$title = 'Laporan Transaksi';
$dari = trim($_GET['dari'] ?? ''); $sampai = trim($_GET['sampai'] ?? ''); $status = trim($_GET['status'] ?? ''); $metode = trim($_GET['metode'] ?? ''); $petugas = trim($_GET['petugas'] ?? ''); $q = trim($_GET['q'] ?? '');
$statuses = ['pending','diproses','dikirim','selesai','dibatalkan']; $methods = ['tunai','qris','duitku']; if (!in_array($status, $statuses, true)) $status = ''; if (!in_array($metode, $methods, true)) $metode = '';
$petugasList = $pdo->query("SELECT id, nama FROM admin_users WHERE role = 'kasir' ORDER BY nama")->fetchAll();
$validPetugas = array_map('strval', array_column($petugasList, 'id'));
if ($petugas !== '' && $petugas !== 'none' && !in_array($petugas, $validPetugas, true)) $petugas = '';
$where=[]; $params=[];
if ($dari !== '') {$where[]='t.tanggal >= ?';$params[]=$dari;} if ($sampai !== '') {$where[]='t.tanggal <= ?';$params[]=$sampai;} if ($status !== '') {$where[]='t.status_pesanan = ?';$params[]=$status;} if ($q !== '') {$where[]='(CAST(t.id_transaksi AS CHAR) LIKE ? OR p.nama LIKE ?)';$params[]="%$q%";$params[]="%$q%";}
if ($metode !== '') {$where[]='COALESCE(t.metode_pembayaran, \'tunai\') = ?';$params[]=$metode;}
$from=' FROM transaksi t INNER JOIN pelanggan p ON p.id_pelanggan=t.id_pelanggan LEFT JOIN admin_users a ON a.id=t.id_petugas';
if ($petugas === 'none') $where[]='t.id_petugas IS NULL'; elseif ($petugas !== '') {$where[]='t.id_petugas = ?';$params[]=(int)$petugas;}
$condition=$where?' WHERE '.implode(' AND ',$where):'';
$st=$pdo->prepare('SELECT t.id_transaksi,t.tanggal,p.nama nama_pelanggan,COALESCE(a.nama,\'Belum tercatat\') petugas,t.nama_barang,t.jumlah,t.total subtotal,t.status_pesanan,COALESCE(t.metode_pembayaran,\'tunai\') metode_pembayaran,t.total diterima'.$from.$condition.' ORDER BY t.tanggal DESC,t.id_transaksi DESC'); $st->execute($params); $rows=$st->fetchAll();
$ss=$pdo->prepare('SELECT COUNT(*) jumlah,COALESCE(SUM(t.total),0) diterima,COALESCE(AVG(t.total),0) rata_rata,COALESCE(SUM(t.jumlah),0) item,COUNT(DISTINCT t.id_pelanggan) pelanggan'.$from.$condition); $ss->execute($params); $summary=$ss->fetch();
$trendSt=$pdo->prepare('SELECT t.tanggal,COUNT(*) jumlah,COALESCE(SUM(t.total),0) total'.$from.$condition.' GROUP BY t.tanggal ORDER BY t.tanggal ASC'); $trendSt->execute($params); $trend=$trendSt->fetchAll();
$topProductSt=$pdo->prepare('SELECT t.nama_barang,COALESCE(SUM(t.jumlah),0) item,COALESCE(SUM(t.total),0) total'.$from.$condition.' GROUP BY t.nama_barang ORDER BY item DESC,total DESC LIMIT 5'); $topProductSt->execute($params); $topProducts=$topProductSt->fetchAll();
$topCustomerSt=$pdo->prepare('SELECT p.nama,COUNT(t.id_transaksi) jumlah,COALESCE(SUM(t.total),0) total'.$from.$condition.' GROUP BY p.id_pelanggan,p.nama ORDER BY total DESC LIMIT 5'); $topCustomerSt->execute($params); $topCustomers=$topCustomerSt->fetchAll();
$staffSummarySt=$pdo->prepare('SELECT COALESCE(a.nama,\'Belum tercatat\') petugas,COUNT(t.id_transaksi) jumlah,COALESCE(SUM(t.total),0) total'.$from.$condition.' GROUP BY t.id_petugas,a.nama ORDER BY total DESC'); $staffSummarySt->execute($params); $staffSummary=$staffSummarySt->fetchAll();
$query=http_build_query(array_filter(['dari'=>$dari,'sampai'=>$sampai,'status'=>$status,'metode'=>$metode,'petugas'=>$petugas,'q'=>$q],static fn($v)=>$v!==''));
if (($_GET['export'] ?? '') === 'csv') {
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename="laporan-tokoku-' . date('Ymd-His') . '.csv"');
    $out = fopen('php://output', 'w'); fputcsv($out, ['ID','Tanggal','Petugas','Pelanggan','Produk','Jumlah','Subtotal','Status','Metode Pembayaran']);
    foreach ($rows as $r) fputcsv($out, [$r['id_transaksi'],$r['tanggal'],$r['petugas'],$r['nama_pelanggan'],$r['nama_barang'],$r['jumlah'],$r['subtotal'],$r['status_pesanan'],$r['metode_pembayaran']]);
    fclose($out); exit;
}
include 'includes/header.php';
?>
<div class="page-heading report-page-heading"><div><span class="eyebrow eyebrow-dark">SALES REPORT</span><h1>Laporan Transaksi Penjualan</h1><p class="sub">Pantau pendapatan penjual berdasarkan transaksi aktual dari database.</p></div><a class="btn print-button" href="laporan_print.php<?= $query?'?'.e($query):'' ?>" target="_blank" rel="noopener"><span aria-hidden="true">▣</span> Cetak Laporan</a></div>
<div class="report-filter-card card"><form method="get" class="report-filter-form"><label>Pencarian<input type="search" name="q" value="<?=e($q)?>" placeholder="ID transaksi atau nama pembeli"></label><label>Dari tanggal<input type="date" name="dari" value="<?=e($dari)?>"></label><label>Sampai tanggal<input type="date" name="sampai" value="<?=e($sampai)?>"></label><label>Status pesanan<select name="status"><option value="">Semua status</option><?php foreach($statuses as $s): ?><option value="<?=e($s)?>" <?=$status===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach; ?></select></label><div class="filter-actions"><button class="btn" type="submit">Terapkan</button><a class="btn sec" href="laporan_transaksi.php">Reset</a></div></form></div>
<div class="report-extra-tools"><div class="quick-periods"><span>Periode cepat:</span><button type="button" class="btn sec sm" data-period="today">Hari ini</button><button type="button" class="btn sec sm" data-period="week">7 hari</button><button type="button" class="btn sec sm" data-period="month">Bulan ini</button></div><form method="get" class="payment-filter"><input type="hidden" name="dari" value="<?=e($dari)?>"><input type="hidden" name="sampai" value="<?=e($sampai)?>"><input type="hidden" name="status" value="<?=e($status)?>"><input type="hidden" name="q" value="<?=e($q)?>"><label>Metode pembayaran<select name="metode"><option value="">Semua metode</option><?php foreach($methods as $m): ?><option value="<?=e($m)?>" <?=$metode===$m?'selected':''?>><?=e(strtoupper($m))?></option><?php endforeach; ?></select></label><button class="btn sm" type="submit">Filter</button></form><a class="btn sec sm" href="laporan_transaksi.php?<?=e($query)?>&amp;export=csv">Ekspor CSV</a></div>
 <div class="report-staff-filter card"><form method="get"><input type="hidden" name="dari" value="<?=e($dari)?>"><input type="hidden" name="sampai" value="<?=e($sampai)?>"><input type="hidden" name="status" value="<?=e($status)?>"><input type="hidden" name="metode" value="<?=e($metode)?>"><input type="hidden" name="q" value="<?=e($q)?>"><label>Filter petugas kasir<select name="petugas"><option value="">Semua petugas</option><option value="none" <?=$petugas==='none'?'selected':''?>>Belum tercatat</option><?php foreach($petugasList as $person): ?><option value="<?=e($person['id'])?>" <?=$petugas===(string)$person['id']?'selected':''?>><?=e($person['nama'])?></option><?php endforeach; ?></select></label><button class="btn" type="submit">Tampilkan Pendapatan</button></form></div>
 <div class="grid report-summary-grid"><div class="stat report-stat"><div class="label">Total transaksi</div><div class="value"><?=e($summary['jumlah'])?></div><span class="stat-note">sesuai filter aktif</span></div><div class="stat report-stat report-stat-income"><div class="label">Total pendapatan</div><div class="value value-small"><?=rupiah($summary['diterima'])?></div><span class="stat-note">akumulasi transaksi</span></div><div class="stat report-stat"><div class="label">Rata-rata transaksi</div><div class="value value-small"><?=rupiah($summary['rata_rata'])?></div><span class="stat-note">nilai per transaksi</span></div><div class="stat report-stat"><div class="label">Barang terjual</div><div class="value"><?=e($summary['item'])?></div><span class="stat-note">total unit produk</span></div><div class="stat report-stat"><div class="label">Pelanggan aktif</div><div class="value"><?=e($summary['pelanggan'])?></div><span class="stat-note">dalam periode filter</span></div></div>
<div class="two report-insight-grid"><section class="card insight-card"><div class="section-heading compact"><div><h2>Tren penjualan</h2><p>Pendapatan per hari sesuai filter.</p></div></div><div class="trend-chart"><?php if($trend): $maxTrend=max(array_map(fn($r)=>(float)$r['total'],$trend)); foreach($trend as $point): $height=$maxTrend>0?max(8,round(((float)$point['total']/$maxTrend)*100)):8; ?><div class="trend-item"><div class="trend-value"><?=rupiah($point['total'])?></div><div class="trend-bar" style="height:<?=$height?>%"></div><small><?=e(date('d M',strtotime($point['tanggal'])))?></small></div><?php endforeach; else: ?><p class="empty">Belum ada data tren.</p><?php endif; ?></div></section><section class="card insight-card"><div class="section-heading compact"><div><h2>Produk terlaris</h2><p>Diurutkan berdasarkan jumlah unit.</p></div></div><?php if($topProducts): ?><div class="ranking-list"><?php foreach($topProducts as $i=>$product): ?><div class="ranking-row"><span class="rank-number"><?=e($i+1)?></span><div><strong><?=e($product['nama_barang'])?></strong><small><?=e($product['item'])?> unit terjual</small></div><b><?=rupiah($product['total'])?></b></div><?php endforeach; ?></div><?php else: ?><p class="empty">Belum ada data produk.</p><?php endif; ?></section></div>
<div class="card insight-card customer-ranking"><div class="section-heading compact"><div><h2>Pelanggan teratas</h2><p>Pelanggan dengan nilai belanja terbesar pada filter aktif.</p></div></div><?php if($topCustomers): ?><div class="customer-rank-grid"><?php foreach($topCustomers as $i=>$customer): ?><div class="customer-rank"><span class="rank-number"><?=e($i+1)?></span><div><strong><?=e($customer['nama'])?></strong><small><?=e($customer['jumlah'])?> transaksi</small></div><b><?=rupiah($customer['total'])?></b></div><?php endforeach; ?></div><?php else: ?><p class="empty">Belum ada data pelanggan.</p><?php endif; ?></div>
<div class="card modern-table-card report-table-card"><div class="section-heading"><div><h2>Daftar transaksi</h2><p><?= $rows?'Data transaksi aktual sesuai filter.':'Belum ada transaksi yang sesuai filter.' ?></p></div><span class="result-count"><?=e($summary['jumlah'])?> transaksi</span></div><div class="table-wrap"><table class="sales-report-table"><thead><tr><th>No.</th><th>ID Transaksi</th><th>Tanggal</th><th>Pembeli</th><th>Produk &amp; Qty</th><th>Subtotal Produk</th><th>Total Diterima Penjual</th><th>Status Pesanan</th><th>Metode Pembayaran</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><td><?=$i+1?></td><td><strong class="transaction-id">#<?=e($r['id_transaksi'])?></strong></td><td class="muted-cell"><?=e(date('d M Y',strtotime($r['tanggal'])))?></td><td><strong><?=e($r['nama_pelanggan'])?></strong></td><td><?=e($r['nama_barang'])?><span class="qty-inline">× <?=e($r['jumlah'])?></span></td><td class="num"><?=rupiah($r['subtotal'])?></td><td class="num received-value"><?=rupiah($r['diterima'])?></td><td><span class="status-badge status-<?=e($r['status_pesanan'])?>"><?=e(ucfirst($r['status_pesanan']))?></span></td><td><span class="payment-method"><?=e(strtoupper($r['metode_pembayaran']))?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="9" class="empty">Tidak ada data transaksi.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card staff-income-card"><div class="section-heading compact"><div><h2>Pendapatan setiap petugas</h2><p>Perbandingan pendapatan berdasarkan petugas yang mencatat transaksi.</p></div></div><div class="staff-income-grid"><?php foreach($staffSummary as $item): ?><div class="staff-income-item"><span class="staff-avatar"><?=e(strtoupper(substr($item['petugas'],0,1)))?></span><div><strong><?=e($item['petugas'])?></strong><small><?=e($item['jumlah'])?> transaksi</small></div><b><?=rupiah($item['total'])?></b></div><?php endforeach; ?><?php if(!$staffSummary): ?><p class="empty">Belum ada data petugas.</p><?php endif; ?></div></div>
<script>
document.querySelectorAll('[data-period]').forEach(button=>button.addEventListener('click',()=>{
 const now=new Date(), from=new Date(now), format=date=>date.toISOString().slice(0,10);
 if(button.dataset.period==='today'){} else if(button.dataset.period==='week'){from.setDate(now.getDate()-6)} else {from.setDate(1);}
 document.querySelector('input[name="dari"]').value=format(from);
 document.querySelector('input[name="sampai"]').value=format(now);
 document.querySelector('.report-filter-form').submit();
}));
</script>
